package com.algoverse;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.data.mongodb.core.query.*;
import static org.springframework.data.mongodb.core.query.Criteria.where;
@RestController @RequestMapping("/api")
public class CoachingController {
 final Store store;CoachingController(Store store){this.store=store;}
 static final List<String> ORDER=List.of("traverse","reverse_string","linear","binary","bubble","selection","insertion","merge","quick","radix","sliding","two_pointer","stack","queue","deque","priority","singly","doubly","circular","bst","bfs_tree","dfs_tree","heap","avl","redblack","bfs_graph","dfs_graph","dijkstra","topological","fibonacci","memoization","knapsack","hash_chaining","hash_probing","hashset");
 static final Map<String,String> RELATED=Map.of("two-sum","hash_chaining","reverse-linked-list","singly","valid-parentheses","stack","merge-sorted-lists","singly","max-subarray","traverse","best-time-stock","traverse","climbing-stairs","fibonacci","debug-sum","traverse");
 static List<String> hints(Data.Problem p){String first=switch(p.id){case "two-sum"->"For each number, ask which other number would make the target.";case "valid-parentheses"->"A closing bracket must match the most recent unmatched opening bracket.";case "reverse-linked-list"->"Think about the order you want to read the input values.";case "merge-sorted-lists"->"Look at the front of both lists. Which value belongs next?";case "max-subarray"->"At each number, choose whether to extend the current group or start again.";case "best-time-stock"->"A purchase must happen before the sale.";case "climbing-stairs"->"The final move comes from one step below or two steps below.";case "debug-sum"->"Test an empty array. What should its sum be?";default->"Walk through the first visible example by hand and identify what changes.";};return List.of(first,p.hint==null||p.hint.isBlank()?"Choose a structure that avoids repeating the same work.":p.hint,switch(p.id){case "two-sum"->"Store earlier numbers with their indices. Check target − current before inserting the current number, so you do not reuse an index.";case "valid-parentheses"->"Push opening brackets onto a stack; pop and compare for closing brackets. At the end, the stack must be empty.";case "max-subarray"->"Keep a running sum and best sum. Start the running sum and best sum with the first value, so all-negative arrays work.";case "best-time-stock"->"Track the lowest price seen so far and the best difference from a later price. Start best profit at zero.";case "climbing-stairs"->"Save ways(1)=1 and ways(2)=2, then add the previous two counts for each later step.";case "debug-sum"->"The starting total must be zero. Starting at one adds an extra one to every answer.";default->"Check empty inputs, repeated values and boundaries before writing the final loop.";});}
 @GetMapping("/problems/{id}/hints") Object hints(@PathVariable String id,HttpServletRequest req){var p=store.byId(id,Data.Problem.class);Errors.check(p!=null&&p.active,"Problem not found.");String key=AuthController.user(req).id+":"+id;var state=store.byId(key,Data.Hints.class);int count=state==null?0:Math.min(state.revealed,3);return Map.of("revealed",count,"total",3,"hints",hints(p).subList(0,count));}
 @PostMapping("/problems/{id}/hints") Object reveal(@PathVariable String id,HttpServletRequest req){var p=store.byId(id,Data.Problem.class);Errors.check(p!=null&&p.active,"Problem not found.");String user=AuthController.user(req).id,key=user+":"+id;store.mongo.upsert(Query.query(where("_id").is(key)),new Update().setOnInsert("userId",user).inc("revealed",1),Data.Hints.class);return hints(id,req);}
 @GetMapping("/roadmap") Object roadmap(HttpServletRequest req){String user=AuthController.user(req).id;var progress=store.progress(user);Set<String> done=new HashSet<>();store.mongo.find(Query.query(where("userId").is(user).and("completed").is(true)),Data.Learning.class).forEach(l->done.add(l.lessonId));var active=store.mongo.find(Query.query(where("active").is(true)),Data.Lesson.class);var byId=new HashMap<String,Data.Lesson>();active.forEach(l->byId.put(l.id,l));List<Map<String,Object>> items=new ArrayList<>();String previous=null;for(String id:ORDER){var lesson=byId.get(id);if(lesson==null)continue;String status=done.contains(id)?"completed":previous==null||done.contains(previous)?"ready":"upcoming";items.add(Map.of("id",id,"title",lesson.title,"summary",lesson.summary,"status",status,"prerequisite",previous==null?"":previous,"minutes",15));previous=id;}
  String recommended=items.stream().filter(i->i.get("status").equals("ready")).map(i->(String)i.get("id")).findFirst().orElse("");String reason="Continue with the next foundation you have not completed.";
  for(var attempt:store.submissions(user,5)){if(!attempt.accepted&&!((List<?>)progress.get("solved")).contains(attempt.problemId)&&attempt.status.equals("Wrong answer")){String related=RELATED.get(attempt.problemId);if(related!=null&&byId.containsKey(related)){recommended=related;reason="Review this lesson after your recent attempt at "+attempt.problemId+". Then retry the problem.";break;}}}
  return Map.of("items",items,"completed",done.stream().filter(byId::containsKey).count(),"total",items.size(),"recommended",recommended,"reason",recommended.isEmpty()?"You completed this roadmap. Try practice problems or quizzes next.":reason,"solved",progress.get("solved"));
 }
}
